#include <iostream>
#include <stdexcept>
#include <string>

void evaluateRisk(int score) {
    if (score < 0) {
        throw std::invalid_argument("Score cannot be negative");
    }
    if (score > 100) {
        throw std::out_of_range("Score exceeds maximum threshold");
    }
    std::cout << "Valid score: " << score << "\n";
}

int main() {
    int testScores[] = {85, -5, 120};

    for (int score : testScores) {
        try {
            evaluateRisk(score);
        } catch (const std::out_of_range& e) {
            std::cout << "Caught specific out_of_range: " << e.what() << "\n";
        } catch (const std::logic_error& e) {
            std::cout << "Caught base logic_error: " << e.what() << "\n";
        } catch (...) {
            std::cout << "Caught unknown exception\n";
        }
    }
    return 0;
}

#include <iostream>
#include <memory>
#include <stdexcept>
#include <string>

class Resource {
public:
    explicit Resource(std::string name) : name_(std::move(name)) {
        std::cout << "Acquired: " << name_ << "\n";
    }
    ~Resource() {
        std::cout << "Released: " << name_ << "\n";
    }
    void doWork(bool fail) {
        if (fail) {
            throw std::runtime_error("Work failed unexpectedly");
        }
        std::cout << "Work completed successfully for " << name_ << "\n";
    }
private:
    std::string name_;
};

void processJob(bool triggerError) {
    std::unique_ptr<Resource> managedRes = std::make_unique<Resource>("ManagedDB");
    Resource localRes("LocalBuffer");
    managedRes->doWork(triggerError);
}

int main() {
    try {
        processJob(true);
    } catch (const std::exception& e) {
        std::cout << "Caught in main: " << e.what() << "\n";
    }
    return 0;
}

#include <iostream>
#include <stdexcept>
#include <string>

void computeInternal(int divisor) {
    if (divisor == 0) {
        throw std::runtime_error("Division by zero in computeInternal");
    }
    std::cout << "Result: " << (100 / divisor) << "\n";
}

void intermediateService(int val) {
    try {
        computeInternal(val);
    } catch (const std::exception& e) {
        std::cout << "[Service Log] Caught error: " << e.what() << ". Rethrowing...\n";
        throw; // Ném lại chính đối tượng ngoại lệ ban đầu
    }
}

int main() {
    try {
        intermediateService(0);
    } catch (const std::runtime_error& e) {
        std::cout << "[Top Level] Handled rethrown runtime error: " << e.what() << "\n";
    }
    return 0;
}
